internal class UPSPricingRuleBuilder_RuleTable extends UPSPricingRuleBuilder
{
    private UPSPricingType pricingType;

    private DialogField ruleTableRuleIdCtrl;
    private DialogField ruleTableNameCtrl;
    private DialogField ruleTableDescriptionCtrl;

}

Method.Source:
public static void main(Args args)
{
    UPSPricingRuleBuilder_RuleTable createRule;
    createRule = new UPSPricingRuleBuilder_RuleTable(args.parmEnum());

    createRule.createRecord();
}

public void new(UPSPricingType _pricingType)
{
    super(UPSPricingAttributeSourceLevel::Header);

    UPSRuleTable ruleTable;
    this.pricingType = _pricingType;

    ruleTable.clear();
    ruleTable.PricingType = _pricingType;
    this.masterRecord = ruleTable;
}

public void initMasterRecord()
{
    if (this.prompt())
    {
        this.dialogOk = true;
    }
    else
    {
        this.dialogOk = false;
    }
}

public void linkPricingRule(UPSPricingRule _pricingRule)
{
    if (this.dialogOk && _pricingRule)
    {
        UPSRuleTable ruletable = masterRecord;
        ruletable.HeaderPricingRule = _pricingRule.RecId;
    }
}

public Object dialog()
{
    DialogRunbase dialog = super();

    dialog.caption("@UnifiedPricingService:UPSPricingRuleBuilder_Dialog_Caption");

    this.ruleTableRuleIdCtrl = dialog.addField(extendedTypeStr(UPSRuleId), "@UnifiedPricingService:UPSRuleId");
    this.ruleTableNameCtrl = dialog.addField(extendedTypeStr(Name), "@SYS7399");
    this.ruleTableDescriptionCtrl = dialog.addField(extendedTypeStr(Description), "@SYS7576");
    return dialog;
}

public boolean getFromDialog()
{
    boolean ret;

    ret = super();

    UPSRuleTable createdRuleTable = masterRecord;

    createdRuleTable.RuleId = ruleTableRuleIdCtrl.value();
    createdRuleTable.Name = ruleTableNameCtrl.value();
    createdRuleTable.Description = ruleTableDescriptionCtrl.value();

    // TODO: handle number sequence

    return ret;
}
